    (v_route, 'Ambras', 'Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 47.25667, 11.43472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Ambras%20Park%20und%20Garten%2010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Ambras%20Park%20und%20Garten%2010.jpg"}'::text[], 0, '{"en": {"name": "Ambras Castle", "description": "Castle in Innsbruck, Austria. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Schloss Ambras", "description": "Schloss in Innsbruck, Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Ambras", "description": "Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Ambras", "description": "Casteel in Innsbruck, Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Ambras", "description": "Palacio en Innbrusck (Austria). Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Ambras", "description": "Château à Innsbruck, Autriche. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Амбрас", "description": "Замок в Інсбруку, Австрія. Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
