    (v_route, 'Katedrála v Innsbrucku', 'Památka v Rakousku — kus historie přímo u trasy.', 47.26936, 11.39417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20zu%20St%20Jakob%20%28IMG%202072%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20zu%20St%20Jakob%20%28IMG%202072%29.jpg"}'::text[], 2, '{"en": {"name": "Innsbruck Cathedral", "description": "Church building in Innsbruck, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Dom zu St. Jakob", "description": "Kirchengebäude in Innsbruck. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jakuba w Innsbrucku", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Innsbruck", "description": "Kathedraal in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santiago", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jacques d''Innsbruck", "description": "Église autrichienne. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Якова", "description": "Головний католицький храм Інсбрука в Австрії. Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
