    (v_route, 'Bazilika svatých Petra a Pavla v Poznani', 'Katedrála v Poznani. Památka v Polsku — kus historie přímo u trasy.', 52.41139, 16.94778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Poznan%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Poznan%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2010.jpg"}'::text[], 0, '{"en": {"name": "Archcathedral Basilica of St. Peter and St. Paul", "description": "Polish cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Posener Dom", "description": "Kirchengebäude in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna Świętych Apostołów Piotra i Pawła w Poznaniu", "description": "Świątynia katolicka, katedra. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Petrus-en-Paulusbasiliek", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Poznań", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saints-Pierre-et-Saint-Paul de Poznan", "description": "Église à Poznań en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святих Петра і Павла", "description": "Катедральний собор в Познані, Польща. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'New Synagogue in Poznań', 'Památka v Polsku — kus historie přímo u trasy.', 52.4108, 16.9351, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poznan%20Stawna%20414-27.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poznan%20Stawna%20414-27.jpg"}'::text[], 1, '{"en": {"name": "New Synagogue in Poznań", "description": "Former Jewish place of worship in Poznan. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Neue Synagoge (Posen)", "description": "Ehemaliges jüdisches Gotteshaus in Posen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Nowa Synagoga w Poznaniu", "description": "Dawne żydowskie miejsce kultu w Poznaniu. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "New Synagogue in Poznań", "description": "Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "New Synagogue in Poznań", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Nouvelle synagogue (Poznan)", "description": "Ancien lieu de culte juif à Poznan. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "New Synagogue in Poznań", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
